// Packs the web board's files (src/web) into src/web/assets.generated.ts, so the bundle and the single executable
// serve them from memory. Run by the test, typecheck and build scripts; the generated file is not committed.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('../src/web/', import.meta.url))
const TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' }
const assets = {}
for (const name of readdirSync(dir).sort()) {
  const ext = name.slice(name.lastIndexOf('.'))
  if (!TYPES[ext] || name.endsWith('.generated.ts')) continue
  assets[`/${name}`] = { type: TYPES[ext], body: readFileSync(dir + name, 'utf8') }
}
writeFileSync(
  `${dir}assets.generated.ts`,
  `// Generated by scripts/web-assets.mjs from the files beside it. Do not edit.\nexport const ASSETS: Record<string, { type: string; body: string }> = ${JSON.stringify(assets, null, 1)}\n`,
)
